let in_ranges_b ranges off =
  existsb (fun r -> fst r <= off && Nat.ltb off (snd r)) ranges

let rec prefix_b needle hay =
  match needle with
  | [] -> true
  | n0 :: nrest -> (
      match hay with
      | [] -> false
      | h0 :: hrest -> n0 = h0 && prefix_b nrest hrest)

let rec contains_b needle hay =
  match hay with
  | [] -> prefix_b needle []
  | _ :: rest -> prefix_b needle hay || contains_b needle rest

let rec first_match toks l =
  match toks with
  | [] -> None
  | t :: rest -> if prefix_b t l then Some t else first_match rest l

