let ref_tokens = [ eqref_tok; autoref_tok; cref_tok; cref_tok0; ref_tok ]

let rec scan_from fuel toks protected pos l =
  (fun fO fS n -> if n = 0 then fO () else fS (n - 1))
    (fun _ -> [])
    (fun f ->
      match l with
      | [] -> []
      | b0 :: rest -> (
          if in_ranges_b protected pos then
            scan_from f toks protected (Stdlib.Int.succ pos) rest
          else
            match first_match toks (b0 :: rest) with
            | Some tok -> (
                match
                  read_key (b0 :: rest) (sub (length tok) (Stdlib.Int.succ 0))
                with
                | Some p ->
                    let key, next = p in
                    (pos, key)
                    :: scan_from f toks protected (add pos next)
                         (skipn next (b0 :: rest))
                | None -> scan_from f toks protected (Stdlib.Int.succ pos) rest)
            | None -> scan_from f toks protected (Stdlib.Int.succ pos) rest))
    fuel

let scan_generic toks src protected =
  scan_from (Stdlib.Int.succ (length src)) toks protected 0 src

let scan_labels src protected = scan_generic (label_tok :: []) src protected
let scan_refs src protected = scan_generic ref_tokens src protected

type scan_event = Ev_def of int * byte list | Ev_ref of int * byte list

let ev_def_of p = Ev_def (fst p, snd p)
let ev_ref_of p = Ev_ref (fst p, snd p)

let rec merge_fuel fuel defs refs =
  (fun fO fS n -> if n = 0 then fO () else fS (n - 1))
    (fun _ -> app (map ev_def_of defs) (map ev_ref_of refs))
    (fun f ->
      match defs with
      | [] -> map ev_ref_of refs
      | p :: ds -> (
          let od, kd = p in
          match refs with
          | [] -> map ev_def_of defs
          | p0 :: rs ->
              let orf, kr = p0 in
              if od <= orf then Ev_def (od, kd) :: merge_fuel f ds refs
              else Ev_ref (orf, kr) :: merge_fuel f defs rs))
    fuel

let merge_events defs refs =
  merge_fuel (add (length defs) (length refs)) defs refs

let two30 = 1073741824
let fnv_basis = 2166136261
let fnv_prime = 16777619
let odd_b n = negb (n = mul (Stdlib.Int.succ (Stdlib.Int.succ 0)) (Nat.div2 n))

let rec lxor_fuel fuel a b =
  (fun fO fS n -> if n = 0 then fO () else fS (n - 1))
    (fun _ -> 0)
