let rec pkg_skip_ws l =
  match l with [] -> [] | b :: tl -> if pkg_is_ws b then pkg_skip_ws tl else l

let not_alpha_head = function [] -> true | b :: _ -> negb (is_alpha_b b)

let after_loader src =
  if
    prefix_b n_usepackage src
    && not_alpha_head (skipn (length n_usepackage) src)
  then Some (skipn (length n_usepackage) src)
  else if
    prefix_b n_requirepackage src
    && not_alpha_head (skipn (length n_requirepackage) src)
  then Some (skipn (length n_requirepackage) src)
  else None

