      then [] :: split_comma tl
      else
        match split_comma tl with
        | [] -> (b :: []) :: []
        | seg :: rest -> (b :: seg) :: rest)

let group_has_pkg pkg grp =
  existsb (fun seg -> bytes_eqb (pkg_trim seg) pkg) (split_comma grp)

let rec uses_package_b pkg src =
  match src with
  | [] -> false
  | _ :: tl -> (
      match after_loader src with
      | Some rest -> (
          match read_brace_group (skip_optional_bracket (pkg_skip_ws rest)) with
          | Some grp ->
              if group_has_pkg pkg grp then true else uses_package_b pkg tl
          | None -> uses_package_b pkg tl)
      | None -> uses_package_b pkg tl)

let detect_body_features src =
  app
    (if
       ((uses_package_b p_fontspec src || contains_b n_setmainfont src)
       || uses_package_b p_polyglossia src)
       || uses_package_b p_mathspec src
     then Opentype_fonts :: []
     else [])
    (app
       (if uses_package_b p_unicode_math src || contains_b n_setmathfont src
        then Unicode_math :: []
        else [])
       (app
          (if uses_package_b p_luacode src || contains_b n_directlua src then
             Lua_scripting :: []
           else [])
          (app
             (if
                (uses_package_b p_cjk src || contains_b n_cjk_begin src)
                || uses_package_b p_luatexja src
              then Japanese_cjk :: []
              else [])
             (if uses_package_b p_inputenc src && contains_b n_utf8 src then
                UTF8_inputenc :: []
              else []))))

