let is_blank src = forallb is_ws src

let token_of_event = function
  | Ev_def (_, k) -> BT_label_def (fnv30 k)
  | Ev_ref (_, k) -> BT_label_ref (fnv30 k)

let body_of_source src protected =
  app
    (map token_of_event
       (merge_events (scan_labels src protected) (scan_refs src protected)))
    (app
       (map (fun x -> BT_needs_feature x) (detect_body_features src))
       (if is_blank src then [] else BT_text :: []))
